@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800;900&family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&display=swap');
:root{color-scheme:dark;--bg:#08121b;--panel:#101d27;--line:#25333d;--muted:#83909a;--white:#f4f3ed;--blue:#2788f5;--orange:#ff633d}
*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:var(--bg);color:var(--white);font-family:Manrope,Arial,sans-serif}body{min-height:100vh;background-image:radial-gradient(ellipse at 42% 42%,#14232d 0,transparent 58%),linear-gradient(135deg,#08121b,#0b161f 65%,#0a141c)}button{font:inherit;color:inherit}.game-shell{max-width:1512px;margin:0 auto;padding:0 56px}.topbar{height:88px;border-bottom:1px solid #25313a;display:flex;align-items:center;justify-content:space-between}.brand{display:flex;align-items:center;gap:12px;color:inherit;text-decoration:none}.brand-mark{width:39px;height:39px;display:grid;place-items:center;border:2px solid #eee;border-radius:50%;font:900 18px 'Barlow Condensed',sans-serif;letter-spacing:-1px;transform:skew(-9deg)}.brand-mark span{color:var(--orange)}.brand-copy{display:grid;gap:2px}.brand-copy strong{font:800 16px 'Barlow Condensed',sans-serif;letter-spacing:1.55px}.brand-copy small{color:#7d8a93;font:9px 'DM Mono',monospace;letter-spacing:1.2px}.top-meta{color:#a6b0b6;font:10px 'DM Mono',monospace;letter-spacing:1.25px}.live-dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:#79d6a0;margin-right:8px;box-shadow:0 0 9px #79d6a066}.meta-divider{color:#4b5962;margin:0 7px}.sound-button{background:none;border:1px solid #34414a;border-radius:3px;padding:8px 11px;color:#d9e0e2;font:14px 'DM Mono',monospace}.sound-button span{font-size:9px;letter-spacing:1px;margin-left:5px}.game-layout{display:grid;grid-template-columns:minmax(0,1fr) 286px;gap:22px;padding-top:24px}.stage-wrap{min-width:0}.stage{position:relative;width:100%;aspect-ratio:1200/760;overflow:hidden;background:#1a4935;border:1px solid #36434a;box-shadow:0 16px 40px #0005}.stage canvas{width:100%;height:100%;display:block}.stage-footer{height:40px;display:flex;align-items:center;justify-content:space-between;color:#91a0a6;font:9px 'DM Mono',monospace;letter-spacing:.8px}.check-icon{display:inline-grid;place-items:center;color:#8ce4a6;border:1px solid #5b9e70;width:14px;height:14px;border-radius:50%;font-style:normal;font-size:9px;margin-right:7px}.footer-right{color:#6e7c84}.footer-right b{font-weight:400;color:#d2d7d2}.footer-slash{padding:0 9px;color:#48565e}.side-panel{display:flex;flex-direction:column;gap:13px}.driver-card,.controls-card{background:linear-gradient(145deg,#13212b,#101b24);border:1px solid #293741;padding:15px 16px}.panel-kicker{display:flex;justify-content:space-between;align-items:center;color:#aab5ba;font:10px 'DM Mono',monospace;letter-spacing:1.1px}.panel-kicker span{color:#71818a;font-size:9px}.car-art{height:150px;position:relative;overflow:hidden;margin:13px -4px 11px;background:#092453}.car-art img{height:100%;width:100%;object-fit:cover;object-position:center 55%;opacity:.94;filter:saturate(.9)}.car-art-shade{position:absolute;inset:30% 0 0;background:linear-gradient(transparent,#07101ccc)}.car-number{position:absolute;top:9px;right:11px;color:#fff;font:800 16px 'Barlow Condensed',sans-serif;font-style:italic;text-shadow:0 2px 6px #000}.art-label{position:absolute;left:10px;bottom:9px;color:#f8f8f4;font:800 9px 'Barlow Condensed',sans-serif;letter-spacing:1.2px;line-height:1.3;text-shadow:0 1px 5px #000}.art-label b{color:#b4d7ff;font-size:7px;letter-spacing:1.5px}.car-name-row{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}.car-name-row h2{font:800 18px 'Barlow Condensed',sans-serif;letter-spacing:.8px;margin:0}.car-name-row p{margin:2px 0 0;color:#84949d;font:9px 'DM Mono',monospace;letter-spacing:.7px}.class-badge{display:grid;place-items:center;width:25px;height:25px;border:1px solid #3389e4;color:#6db2ff;font:700 14px 'Barlow Condensed',sans-serif}.stat-row{display:grid;grid-template-columns:88px 1fr 19px;align-items:center;gap:8px;margin:9px 0;color:#98a5ab;font:8px 'DM Mono',monospace;letter-spacing:.3px}.stat-row b{color:#d7e0e2;font-weight:400;text-align:right}.stat-track{height:3px;background:#293741}.stat-track i{height:100%;display:block;background:linear-gradient(90deg,#2076d9,#63bbff)}.controls-card{padding:15px 16px 12px}.key-grid{display:flex;align-items:center;gap:13px;margin-top:12px}.key-grid.compact{margin-top:9px}.key-set{width:57px;display:flex;flex-direction:column;align-items:center;gap:3px}.key-set>div{display:flex;gap:3px}.key-set kbd{width:17px;height:18px;text-align:center;padding-top:2px;background:#202e38;border:1px solid #394751;border-bottom-width:2px;border-radius:3px;color:#d6dedf;font:9px 'DM Mono',monospace}.key-grid p{margin:0;display:grid;gap:3px}.key-grid p b{font:9px 'DM Mono',monospace;letter-spacing:.8px;color:#d5dcdd}.key-grid p small{font-size:9px;color:#7f8e97}.controls-hint{border-top:1px solid #26343d;margin-top:12px;padding-top:9px;color:#718089;font-size:9px;line-height:1.5}.tip-card{display:flex;gap:10px;align-items:flex-start;padding:11px 13px;border:1px solid #44382c;background:#211e1a;color:#a9a29a}.tip-card>span{font-size:15px;color:#efa557}.tip-card p{margin:0;font-size:9px;line-height:1.5}.tip-card b{display:block;color:#e3b478;font:9px 'DM Mono',monospace;letter-spacing:.6px;margin-bottom:3px}.page-footer{display:flex;justify-content:space-between;padding:18px 0 22px;margin-top:8px;border-top:1px solid #1d2b34;color:#67757e;font:8px 'DM Mono',monospace;letter-spacing:1px}.page-footer b{color:#e15f4d;margin-left:3px}.start-screen,.finish-screen{position:absolute;inset:0;display:flex;align-items:center;background:linear-gradient(90deg,#09121bed 0%,#09121bd9 35%,#09121b24 77%,transparent);z-index:3}.start-card{margin-left:7%;margin-top:1%;max-width:360px}.eyebrow{display:flex;align-items:center;gap:8px;color:#aeb8bc;font:9px 'DM Mono',monospace;letter-spacing:1.4px}.eyebrow>span{width:17px;height:1px;background:var(--orange)}.start-card h1{font:900 clamp(42px,5.1vw,74px)/.83 'Barlow Condensed',sans-serif;letter-spacing:-1.5px;margin:22px 0 13px}.start-card h1 em{font-style:normal;color:#4ea0f8}.start-card p{font-size:11px;color:#bdc5c6;letter-spacing:.2px;margin:0 0 21px}.primary-button{display:flex;justify-content:space-between;align-items:center;width:232px;padding:0 14px;height:42px;border:0;background:#f1f0e9;color:#111a20;cursor:pointer;font:800 10px 'DM Mono',monospace;letter-spacing:.6px;transition:background .15s,transform .15s}.primary-button:hover{background:#fff;transform:translateY(-2px)}.primary-button b{font-size:17px;color:#2479d3}.start-note{margin-top:11px;color:#8c989e;font:9px 'DM Mono',monospace}.keycap{display:inline-grid;place-items:center;border:1px solid #59636a;border-radius:2px;width:19px;height:17px;color:#d8dddc;margin-right:4px}.track-stamp{position:absolute;right:5%;top:8%;display:flex;align-items:center;gap:9px;color:#e6e9e3;font:700 9px 'DM Mono',monospace;letter-spacing:.5px;line-height:1.25}.track-stamp>span{font:900 32px 'Barlow Condensed',sans-serif;color:#f4f1e8}.track-stamp small{font-size:7px;color:#a4b0ad}.race-hud{position:absolute;z-index:2;inset:0 0 auto;display:flex;align-items:flex-start;justify-content:space-between;padding:16px 19px;background:linear-gradient(#08131bc9,transparent);pointer-events:none}.hud-block{display:grid;gap:3px}.hud-label{font:8px 'DM Mono',monospace;letter-spacing:1.25px;color:#c5cfcd}.hud-block strong{font:800 24px/.95 'Barlow Condensed',sans-serif;letter-spacing:.2px;color:#fff}.hud-block strong i{font:500 11px 'DM Mono',monospace;color:#a9b5b4;font-style:normal}.lap-dots{display:flex;gap:4px;margin-top:3px}.lap-dots b{width:15px;height:3px;background:#66716f}.lap-dots b.active{background:#71d99c}.position-block{text-align:center}.position-block small,.time-block small{color:#9ba9a6;font:7px 'DM Mono',monospace;letter-spacing:.6px}.speed-block{text-align:center}.speed-block strong{font-size:29px}.speed-block .hud-label{font-size:7px}.time-block{text-align:right}.time-block strong{font:17px 'DM Mono',monospace}.countdown{position:absolute;z-index:4;inset:0;display:grid;place-items:center;color:#fff;font:900 110px 'Barlow Condensed',sans-serif;text-shadow:0 4px 30px #000;animation:pop .45s ease both}.toast{position:absolute;z-index:4;top:27%;left:50%;transform:translateX(-50%);padding:10px 18px;background:#07121ddd;border:1px solid #ffffff44;color:#fff;font:800 14px 'Barlow Condensed',sans-serif;letter-spacing:2px;white-space:nowrap;animation:pop .25s ease both}.finish-screen{align-items:center;justify-content:center;background:#07121bbd;backdrop-filter:blur(3px);z-index:5}.finish-card{text-align:center;width:min(330px,90%);padding:26px 30px;background:#101d27;border:1px solid #52616a;box-shadow:0 10px 60px #0008}.finish-card .eyebrow{justify-content:center}.finish-card h2{font:900 48px 'Barlow Condensed',sans-serif;color:#63acff;margin:8px 0 0}.finish-card p{color:#a7b3b6;font-size:11px;margin:0 0 19px}.finish-time{border-top:1px solid #2d3b44;border-bottom:1px solid #2d3b44;padding:11px;margin-bottom:17px;display:grid;gap:5px}.finish-time small{font:8px 'DM Mono',monospace;letter-spacing:1px;color:#91a0a4}.finish-time strong{font:24px 'DM Mono',monospace}.finish-card .primary-button{margin:auto}.mobile-controls{display:none}.corner-tag{position:absolute;bottom:10px;left:13px;color:#d8e2d9;font:8px 'DM Mono',monospace;letter-spacing:.6px;text-shadow:0 1px 4px #000;z-index:1}.corner-tag span{color:#83d6a0;padding:0 3px}@keyframes pop{from{transform:scale(.7);opacity:0}to{opacity:1}}
@media(max-width:980px){.game-shell{padding:0 24px}.game-layout{grid-template-columns:minmax(0,1fr) 250px;gap:15px}.car-art{height:125px}.side-panel{gap:9px}.driver-card,.controls-card{padding:12px}.topbar{height:74px}}
@media(max-width:760px){.game-shell{padding:0 14px}.topbar{height:64px}.top-meta{font-size:8px}.brand-mark{width:34px;height:34px}.brand-copy strong{font-size:14px}.brand-copy small{font-size:7px}.game-layout{grid-template-columns:1fr;padding-top:12px;gap:10px}.stage{aspect-ratio:1.28}.side-panel{display:grid;grid-template-columns:1fr 1fr;gap:9px}.driver-card{grid-row:span 2}.car-art{height:128px}.tip-card{display:none}.page-footer{margin-top:6px;padding:12px 0 16px}.start-card{margin-left:6%;max-width:260px}.start-card h1{font-size:clamp(35px,8vw,52px);margin:14px 0 9px}.start-card p{font-size:9px;margin-bottom:12px}.eyebrow{font-size:7px}.primary-button{width:190px;height:36px;font-size:8px}.track-stamp{right:4%;top:7%;font-size:7px}.track-stamp>span{font-size:24px}.track-stamp small{font-size:6px}.race-hud{padding:9px 10px}.hud-label{font-size:6px}.hud-block strong{font-size:18px}.hud-block strong i{font-size:8px}.hud-block.position-block small,.time-block small{font-size:6px}.speed-block strong{font-size:22px}.time-block strong{font-size:12px}.corner-tag{font-size:6px;bottom:5px;left:6px}.mobile-controls{position:absolute;z-index:2;bottom:8px;right:8px;display:flex;align-items:flex-end;gap:7px;opacity:.92}.mobile-controls button{border:1px solid #ffffff77;background:#101d25d9;color:#fff;touch-action:none;user-select:none;-webkit-user-select:none}.steer-controls,.drive-controls{display:flex;gap:5px;align-items:flex-end}.steer-controls button{width:39px;height:39px;border-radius:50%;font-size:13px}.drive-controls button{height:40px;border-radius:4px;padding:0 9px;font:700 8px 'DM Mono',monospace;letter-spacing:.4px}.drive-controls .gas-control{background:#16814cdd;border-color:#76dc9a;width:55px}.gas-control span{display:block;font-size:10px}.drive-controls .brake-control{width:44px;background:#a53c34dd}.mobile-controls button.pressed{filter:brightness(1.6);transform:scale(.95)}.stage-footer{height:32px;font-size:7px}.side-panel .controls-card{padding:11px}.controls-hint{font-size:8px}.key-grid p small{font-size:8px}}
@media(max-width:450px){.game-shell{padding:0 9px}.top-meta{display:none}.topbar{height:57px}.sound-button{padding:6px 8px}.game-layout{padding-top:8px}.stage{aspect-ratio:1.06}.side-panel{grid-template-columns:1fr 1fr}.car-art{height:98px}.driver-card,.controls-card{padding:9px}.car-name-row h2{font-size:15px}.stat-row{grid-template-columns:68px 1fr 15px;gap:4px;font-size:7px}.start-card{margin-left:5%;max-width:225px}.start-card h1{font-size:38px}.start-card p{max-width:165px}.start-note{font-size:7px}.track-stamp{transform:scale(.85);transform-origin:top right}.stage-footer{font-size:6px}.footer-right{font-size:6px}.mobile-controls{gap:4px;right:5px;bottom:6px}.steer-controls,.drive-controls{gap:3px}.steer-controls button{width:33px;height:35px}.drive-controls button{height:36px;padding:0 6px}.drive-controls .gas-control{width:47px}.drive-controls .brake-control{width:38px}.lap-dots b{width:11px}}

(() => {
  'use strict';
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const W = 1200, H = 760, CX = 600, CY = 380, RX = 400, RY = 250;
  const ROAD = 104, TAU = Math.PI * 2, TOTAL_LAPS = 3;
  const $ = id => document.getElementById(id);
  const ui = {
    start: $('startScreen'), startButton: $('startButton'), raceHud: $('raceHud'), countdown: $('countdown'),
    finish: $('finishScreen'), finishTitle: $('finishTitle'), finishCopy: $('finishCopy'), finishTime: $('finishTime'),
    lap: $('lapValue'), position: $('positionValue'), speed: $('speedValue'), time: $('timeValue'), best: $('bestValue'),
    dots: $('lapDots'), toast: $('toast'), record: $('recordInline'), sound: $('soundToggle'), again: $('againButton')
  };
  const keys = new Set(), touch = new Set();
  let fit = {scale: 1, x: 0, y: 0}, lastFrame = 0, state = 'intro', countdownTimer = 0, elapsed = 0, distanceProgress = 0;
  let toastTimer = 0, paused = false, audio = null, muted = false, bestTime = Number(localStorage.getItem('blueThunderBest') || 0);
  const car = {x: CX, y: CY - RY, heading: 0, speed: 0, steer: 0, offroad: false};
  const rivals = [
    {name:'04', color:'#e9503e', t:-Math.PI/2 - .18, speed:177, phase:0},
    {name:'12', color:'#e9c94e', t:-Math.PI/2 - .37, speed:167, phase:0},
    {name:'21', color:'#e9eee8', t:-Math.PI/2 - .57, speed:160, phase:0}
  ];
  const scenery = [];
  let seed = 1201;
  function rand(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;}
  for(let i=0;i<118;i++){
    const a=rand()*TAU, r=rand();
    const outer=rand()<.72;
    const dist=outer ? 320+rand()*105 : 125+rand()*100;
    scenery.push({x:CX+Math.cos(a)*(RX+dist),y:CY+Math.sin(a)*(RY+dist),size:5+rand()*10,tone:rand(),kind:rand()<.7?'tree':'rock'});
  }
  function resize(){
    const rect=canvas.getBoundingClientRect();
    const dpr=Math.min(window.devicePixelRatio||1,2);
    canvas.width=Math.max(1,Math.round(rect.width*dpr));canvas.height=Math.max(1,Math.round(rect.height*dpr));
    fit.scale=Math.min(canvas.width/W,canvas.height/H);fit.x=(canvas.width-W*fit.scale)/2;fit.y=(canvas.height-H*fit.scale)/2;
  }
  new ResizeObserver(resize).observe(canvas); resize();
  function anglePoint(t,rx=RX,ry=RY){return {x:CX+Math.cos(t)*rx,y:CY+Math.sin(t)*ry};}
  function pathEllipse(rx,ry){ctx.beginPath();ctx.ellipse(CX,CY,rx,ry,0,0,TAU);}
  function formatTime(s){if(!Number.isFinite(s)||s<0)return '00:00.0';const m=Math.floor(s/60),sec=Math.floor(s%60),d=Math.floor((s%1)*10);return `${String(m).padStart(2,'0')}:${String(sec).padStart(2,'0')}.${d}`;}
  function setToast(text,duration=1300){ui.toast.textContent=text;ui.toast.hidden=false;toastTimer=duration;}
  function beep(freq=520,duration=.11){if(muted)return;try{audio ||= new (window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();const osc=audio.createOscillator(),gain=audio.createGain();osc.type='square';osc.frequency.value=freq;gain.gain.setValueAtTime(.035,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);osc.connect(gain);gain.connect(audio.destination);osc.start();osc.stop(audio.currentTime+duration);}catch(_){}}
  function startRace(){
    if(state==='countdown'||state==='racing')return;
    state='countdown';paused=false;elapsed=0;distanceProgress=0;
    car.x=CX;car.y=CY-RY;car.heading=0;car.speed=0;car.steer=0;car.offroad=false;
    rivals[0].t=-Math.PI/2-.18;rivals[1].t=-Math.PI/2-.37;rivals[2].t=-Math.PI/2-.57;
    rivals.forEach(r=>r.phase=0);
    ui.start.hidden=true;ui.finish.hidden=true;ui.raceHud.hidden=false;ui.countdown.hidden=false;ui.countdown.textContent='3';countdownTimer=3;
    updateHud();beep(330,.12);
  }
  function finishRace(){
    state='finished';ui.countdown.hidden=true;ui.finish.hidden=false;
    const won=playerPosition()===1;
    ui.finishTitle.textContent=won?'¡VICTORIA!':'¡A META!';ui.finishTitle.style.color=won?'#63acff':'#ffb46b';
    ui.finishCopy.textContent=won?'Has conquistado el circuito. ¡Impecable!':'Carrera terminada. La próxima curva es tuya.';
    ui.finishTime.textContent=formatTime(elapsed);
    if(!bestTime||elapsed<bestTime){bestTime=elapsed;localStorage.setItem('blueThunderBest',String(bestTime));updateBest();}
    beep(won?760:430,.28);
  }
  function updateBest(){const s=bestTime?formatTime(bestTime):'—:—.—';ui.best.textContent=`MEJOR ${s}`;ui.record.textContent=s;}
  updateBest();
  function playerPosition(){
    const own=distanceProgress/(TAU);
    let ahead=0;
    for(const r of rivals){const their=r.phase+(r.t+Math.PI/2)/TAU; if(their>own)ahead++;}
    return ahead+1;
  }
  function beginPlaying(){state='racing';ui.countdown.textContent='¡YA!';beep(780,.2);setTimeout(()=>{if(state==='racing')ui.countdown.hidden=true;},380);}
  function togglePause(){if(state!=='racing')return;paused=!paused;if(paused){ui.countdown.hidden=false;ui.countdown.textContent='PAUSA';}else ui.countdown.hidden=true;}
  function held(...codes){return codes.some(code=>keys.has(code)||touch.has(code));}
  window.addEventListener('keydown',e=>{
    if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' ','Enter'].includes(e.key))e.preventDefault();
    if(e.repeat)return;keys.add(e.key.toLowerCase());
    if((e.key==='Enter'||e.key===' ')&&(state==='intro'||state==='finished')){startRace();return;}
    if(e.key.toLowerCase()==='p'||e.key==='Escape')togglePause();
  });
  window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
  window.addEventListener('blur',()=>{keys.clear();touch.clear();});
  ui.startButton.addEventListener('click',startRace);ui.again.addEventListener('click',startRace);
  ui.sound.addEventListener('click',()=>{muted=!muted;ui.sound.classList.toggle('muted',muted);ui.sound.innerHTML=muted?'♫ <span>OFF</span>':'♫ <span>SONIDO</span>';if(!muted)beep(600,.08);});
  document.querySelectorAll('[data-control]').forEach(button=>{
    const control=button.dataset.control;
    const down=e=>{e.preventDefault();touch.add(control);button.classList.add('pressed');if(state==='intro')startRace();};
    const up=e=>{e.preventDefault();touch.delete(control);button.classList.remove('pressed');};
    button.addEventListener('pointerdown',down);button.addEventListener('pointerup',up);button.addEventListener('pointercancel',up);button.addEventListener('pointerleave',up);
  });
  function update(dt){
    if(toastTimer>0){toastTimer-=dt*1000;if(toastTimer<=0)ui.toast.hidden=true;}
    if(state==='countdown'){
      countdownTimer-=dt;
      const num=Math.max(1,Math.ceil(countdownTimer));ui.countdown.textContent=countdownTimer<=0?'¡YA!':String(num);
      if(countdownTimer<=0)beginPlaying();return;
    }
    if(state!=='racing'||paused)return;
    elapsed+=dt;
    const gas=held('w','arrowup','gas'),brake=held('s','arrowdown',' ','brake');
    const left=held('a','arrowleft','left'),right=held('d','arrowright','right');
    const steerInput=(right?1:0)-(left?1:0);
    const t=Math.atan2((car.y-CY)/RY,(car.x-CX)/RX);
    const near=anglePoint(t);const trackDistance=Math.hypot(car.x-near.x,car.y-near.y);
    const onRoad=trackDistance<ROAD*.58;
    car.offroad=!onRoad;
    if(car.offroad&&!car.wasOffroad)setToast('¡FUERA DE PISTA!',850);
    car.wasOffroad=car.offroad;
    const accel=car.offroad?88:157;
    if(gas)car.speed+=accel*dt;else car.speed-=35*dt;
    if(brake)car.speed-=220*dt;
    const maxSpeed=car.offroad?135:252;
    car.speed=Math.max(0,Math.min(maxSpeed,car.speed));
    if(!onRoad)car.speed=Math.max(0,car.speed-65*dt);
    car.steer=steerInput;
    const speedFactor=Math.min(1,car.speed/95);
    car.heading+=steerInput*1.72*speedFactor*dt;
    // Gentle arcade steering assist keeps the car controllable while preserving player input.
    const side=car.x-CX, down=car.y-CY;
    const routeT=Math.atan2(down/RY,side/RX);
    const targetHeading=Math.atan2(RY*Math.cos(routeT),-RX*Math.sin(routeT));
    let headingDiff=Math.atan2(Math.sin(targetHeading-car.heading),Math.cos(targetHeading-car.heading));
    if(speedFactor>.08){
      const curvatureAssist=onRoad?(steerInput===0?.34:.105):.025;
      car.heading+=headingDiff*curvatureAssist*speedFactor*dt;
    }
    car.x+=Math.cos(car.heading)*car.speed*dt;car.y+=Math.sin(car.heading)*car.speed*dt;
    // Circuit edge recovery: scrub speed and gently return a stranded car to the asphalt.
    if(car.x<68||car.x>1132||car.y<62||car.y>698){car.x=Math.max(68,Math.min(1132,car.x));car.y=Math.max(62,Math.min(698,car.y));car.speed*=.65;}
    const newT=Math.atan2((car.y-CY)/RY,(car.x-CX)/RX);
    const delta=Math.atan2(Math.sin(newT-update.lastT),Math.cos(newT-update.lastT));
    if(Number.isFinite(delta))distanceProgress+=delta;
    update.lastT=newT;
    for(const r of rivals){
      const deriv=Math.hypot(RX*Math.sin(r.t),RY*Math.cos(r.t));
      r.t+=r.speed*dt/deriv;r.phase=0;
      if(r.t>=Math.PI*1.5){r.t-=TAU;r.phase++;}
      if(r.t<-Math.PI/2){r.t+=TAU;r.phase--;}
    }
    // Reset progress-angle anchor on race start, preserving smooth unwrapped lap distance.
    const lap=Math.max(0,Math.floor(distanceProgress/TAU));
    ui.lap.textContent=String(Math.min(TOTAL_LAPS,lap+1)).padStart(2,'0');
    const children=ui.dots.children;for(let i=0;i<children.length;i++)children[i].classList.toggle('active',i<=lap);
    ui.position.textContent=playerPosition();ui.speed.textContent=String(Math.round(car.speed*.83)).padStart(3,'0');
    ui.time.textContent=formatTime(elapsed);
    if(lap>update.lastLap){update.lastLap=lap;if(lap>0&&lap<TOTAL_LAPS){setToast(`VUELTA ${lap+1} · ¡SIGUE ASÍ!`,1300);beep(610,.12);}}
